// Built-in, static meal-idea database for the "Browse Meal Ideas" feature.
// This ships in the app bundle — it is NOT stored per-family and has no
// server-side table; cuisine/prep-time/kid-friendly/meal-type only exist
// here for browsing/filtering. Picking one converts it into a real
// SavedMeal via the existing POST /api/saved-meals shape (name, notes,
// directions, ingredients: [{item, quantity, displayOrder}]) — see
// toSavedMealPayload().
//
// `directions` on every entry is original writing — general, standard
// technique for that type of dish, written from scratch for this app, not
// copied or adapted from any specific recipe site. There's deliberately no
// `recipeUrl`/`sourceName` on these entries, since they aren't sourced from
// one real place — that attribution only makes sense for a meal actually
// pulled in via "Import a recipe from a URL" or "Snap a Recipe", which credit
// the real source they read.

export type Cuisine =
  | "American" | "Italian" | "Mexican" | "Asian" | "Mediterranean" | "Indian" | "Breakfast";

export type MealType = "breakfast" | "lunch" | "dinner" | "snack" | "side";

export interface MealIdea {
  id: string;
  name: string;
  cuisine: Cuisine;
  mealType: MealType;
  prepMinutes: number; // rough total prep+cook time
  kidFriendly: boolean;
  ingredients: string[]; // "quantity item" free text, split on first save
  /** Numbered steps as one string ("1. ...\n2. ..."), matching the shape
      Snap a Recipe / Import from URL already produce. */
  directions: string;
}

function ing(...items: string[]): string[] {
  return items;
}

function steps(...items: string[]): string {
  return items.map((s, i) => `${i + 1}. ${s}`).join("\n");
}

