export const CUISINES: Cuisine[] = ["American", "Italian", "Mexican", "Asian", "Mediterranean", "Indian", "Breakfast"];
export const MEAL_TYPES: { value: MealType; label: string }[] = [
  { value: "breakfast", label: "Breakfast" },
  { value: "lunch", label: "Lunch" },
  { value: "dinner", label: "Dinner" },
  { value: "snack", label: "Snack" },
  { value: "side", label: "Side" },
];

export function prepTimeBucket(minutes: number): "quick" | "medium" | "long" {
  if (minutes <= 20) return "quick";
  if (minutes <= 45) return "medium";
  return "long";
}

export const PREP_TIME_BUCKETS: { value: "quick" | "medium" | "long"; label: string }[] = [
  { value: "quick", label: "Quick (≤20 min)" },
  { value: "medium", label: "Medium (21–45 min)" },
  { value: "long", label: "Long (45+ min)" },
];

// Parses a "quantity item" string like "1.5 lb ground beef" into
// { quantity, item } for the existing SavedMealIngredient shape — the
// built-in database stores ingredients as one combined string for
// readability, but the real API wants them split.
function splitIngredient(text: string): { quantity: string | null; item: string } {
  const match = text.match(/^([\d.\/\s]+(?:tbsp|tsp|cup|cups|lb|lbs|oz|can|cans|bunch|head|heads|slices?|cloves?)?\.?)\s+(.+)$/i);
  if (match && match[1].trim()) {
    return { quantity: match[1].trim(), item: match[2].trim() };
  }
  return { quantity: null, item: text };
}

/** Converts a browsed MealIdea into the exact payload POST /api/saved-meals expects. */
export function toSavedMealPayload(idea: MealIdea) {
  return {
    name: idea.name,
    notes: `${idea.cuisine} • ${idea.mealType} • ~${idea.prepMinutes} min${idea.kidFriendly ? " • kid-friendly" : ""}`,
    directions: idea.directions,
    ingredients: idea.ingredients.map((text, i) => {
      const { quantity, item } = splitIngredient(text);
      return { item, quantity, displayOrder: i };
    }),
  };
}
